create or replace function public.super_delete_store(p_store_id uuid) returns void language plpgsql security definer set search_path = public, extensions, auth as $$ declare r record; v_owner uuid; v_pass int; v_left int; begin if not exists (select 1 from public.super_admins where user_id = auth.uid()) then raise exception 'শুধু সুপার এডমিন মুছতে পারবে'; end if; if p_store_id = public.main_store_id() then raise exception 'মূল দোকান মুছা যাবে না'; end if; if not exists (select 1 from public.stores where id = p_store_id) then raise exception 'স্টোর পাওয়া যায়নি'; end if; select id into v_owner from public.profiles where store_id = p_store_id and role = 'admin' limit 1; update public.profiles set store_id = null, role = 'user' where store_id = p_store_id; for v_pass in 1..6 loop v_left := 0; for r in select c.table_name from information_schema.columns c join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name where c.table_schema = 'public' and c.column_name = 'store_id' and t.table_type = 'BASE TABLE' and c.table_name not in ('stores','profiles') loop begin execute format('delete from public.%I where store_id = $1', r.table_name) using p_store_id; exception when foreign_key_violation then v_left := v_left + 1; end; end loop; exit when v_left = 0; end loop; delete from public.stores where id = p_store_id; if v_owner is not null and not exists (select 1 from public.super_admins where user_id = v_owner) then begin delete from public.profiles where id = v_owner; delete from auth.users where id = v_owner; exception when others then null; end; end if; end $$; grant execute on function public.super_delete_store(uuid) to authenticated; select 'OK' as result;
